pm.test("El login responde 200", function () {
  pm.response.to.have.status(200);
});

const respuesta = pm.response.json();

pm.test("El login confirma el acceso", function () {
  pm.expect(respuesta.mensaje).to.eql("Inicio de sesión correcto");
});

pm.test("La respuesta contiene un token", function () {
  pm.expect(respuesta.token).to.be.a("string").and.not.empty;
});

pm.environment.set("token", respuesta.token);

pm.test("La reserva responde con 201", function () {
  pm.response.to.have.status(201);
});

pm.test("La respuesta viene en formato JSON", function () {
  pm.expect(pm.response.headers.get("Content-Type"))
    .to.include("application/json");
});

pm.test("La respuesta contiene información", function () {
  pm.expect(pm.response.text()).to.not.be.empty;
});

